import sys
from collections import Counter

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    dice = []
    for _ in range(n):
        k = int(data[idx]); idx += 1
        faces = data[idx:idx+k]
        idx += k
        c = Counter(faces)
        dice.append((k, c))

    best = 0.0
    for i in range(n):
        ki, ci = dice[i]
        for j in range(i+1, n):
            kj, cj = dice[j]
            if len(ci) > len(cj):
                a, b = cj, ci
            else:
                a, b = ci, cj
            s = 0
            for v, cnt in a.items():
                if v in b:
                    s += cnt * b[v]
            p = s / (ki * kj)
            if p > best:
                best = p
    print(f"{best:.15f}")

